// ❌ OLD: In React 17 and earlier, state updates inside async callbacks
// (fetch, setTimeout) were NOT batched, triggering multiple expensive re-renders.
import { useState } from 'react';

export default function AsyncCounter() {
  const [count, setCount] = useState(0);
  const [flag, setFlag] = useState(false);

  function handleClick() {
    fetch('/api/data').then(() => {
      // In React 17: Renders TWICE (once for count, once for flag)
      setCount((c) => c + 1);
      setFlag((f) => !f);
    });
  }

  console.log('Rendered!');
  return <button onClick={handleClick}>{count} - {String(flag)}</button>;
}

// ✅ NEW: React 18+ automatically batches all updates in promises, timers, and native events.
import { useState } from 'react';

export default function AsyncCounter() {
  const [count, setCount] = useState(0);
  const [flag, setFlag] = useState(false);

  function handleClick() {
    fetch('/api/data').then(() => {
      // In React 18+: Batched into EXACTLY ONE re-render
      setCount((c) => c + 1);
      setFlag((f) => !f);
    });
  }

  console.log('Rendered!'); // Logs once per click
  return <button onClick={handleClick}>{count} - {String(flag)}</button>;
}
